// ASSETS is generated by build.mjs. This Worker does not store user files.
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.hostname === "ngd.fnbapp.net") {
      return Response.redirect("https://ndg.fnbapp.net" + url.pathname + url.search, 308);
    }
    const head = request.method === "HEAD";
    if (request.method !== "GET" && !head) {
      return new Response("Method Not Allowed", {status: 405, headers: {Allow: "GET, HEAD"}});
    }
    const path = url.pathname === "/privacy/" ? "/privacy" : url.pathname;
    const asset = ASSETS[path];
    let body, type, status = 200, cache = "public, max-age=300";
    if (asset) {
      ({body, type} = asset);
      if (path === "/style.css" || path === "/favicon.svg") cache = "public, max-age=86400";
    } else if (path === "/healthz") {
      body = JSON.stringify({status: "ok", service: "ndg-official-site"});
      type = "application/json; charset=utf-8";
      cache = "no-store";
    } else if (path === "/robots.txt") {
      body = "User-agent: *\nAllow: /\nSitemap: https://ndg.fnbapp.net/sitemap.xml\n";
      type = "text/plain; charset=utf-8";
    } else if (path === "/sitemap.xml") {
      body = '<?xml version="1.0" encoding="utf-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://ndg.fnbapp.net/</loc></url><url><loc>https://ndg.fnbapp.net/privacy</loc></url></urlset>';
      type = "application/xml; charset=utf-8";
    } else {
      body = "Not Found";
      type = "text/plain; charset=utf-8";
      status = 404;
      cache = "no-store";
    }
    const headers = {
      "Content-Type": type,
      "Cache-Control": cache,
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
      "X-Frame-Options": "DENY",
      "Content-Security-Policy": "default-src 'none'; img-src 'self' https://raw.githubusercontent.com; style-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"
    };
    return new Response(head ? null : body, {status, headers});
  }
};
